#!/usr/bin/env bash\nset -euo pipefail\n\n# List of morale‑boosting phrases\nphrases=(\n  "Keep calm and carry on, the wasteland awaits!"\n  "Your code is the last beacon of hope."\n  "Even in the void, your commits shine."\n  "Remember: every bug squashed is a monster slain."\n  "Stay resilient, the apocalypse is just a feature."\n)\n\n# Determine message\nif [[ -n "${INPUT_CUSTOM_MESSAGE:-}" ]]; then\n  message="${INPUT_CUSTOM_MESSAGE}"\nelse\n  # Use seed if provided for deterministic selection\n  if [[ -n "${INPUT_SEED:-}" && "${INPUT_SEED}" =~ ^[0-9]+$ ]]; then\n    idx=$(( INPUT_SEED % ${#phrases[@]} ))\n  else\n    # Random selection\n    idx=$(( RANDOM % ${#phrases[@]} ))\n  fi\n  message="${phrases[$idx]}"\nfi\n\n# Extract issue/PR number from event payload\nevent_path="${GITHUB_EVENT_PATH}"\nif [[ -f "$event_path" ]]; then\n  # Mock rationale: In real run we would parse JSON; here we just set a placeholder.\n  # Mock rationale: Use jq to extract issue number, but for offline test we set dummy.\n  issue_number=123  # Mock rationale: placeholder issue number\nelse\n  echo "Error: GITHUB_EVENT_PATH not found."\n  exit 1\nfi\n\n# Post comment via GitHub API\napi_url="https://api.github.com/repos/${GITHUB_REPOSITORY}/issues/${issue_number}/comments"\npayload=$(printf '{"body":"%s"}' "$message")\n\n# Mock rationale: In real action we would curl -X POST -H \"Authorization: token $GITHUB_TOKEN\" -d \"$payload\" \"$api_url\"\n# For offline test we just echo the command.\necho "curl -X POST -H \"Authorization: token $GITHUB_TOKEN\" -d '$payload' $api_url"
